import re, os, json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=9 and not seen[i][j]:
                # flood fill object
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and g[nr][nc]==g[i][j]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                H=max(rs)-min(rs)+1
                fill=7 if H%2 else 2
                for r in range(min(rs)+1,max(rs)):
                    for c in range(min(cs)+1,max(cs)):
                        if g[r][c]==9: out[r][c]=fill
    return out

