from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and g[nr][nc]==g[i][j]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                fill=7 if (max(rs)-min(rs)+1)%2 else 2
                for r in range(min(rs)+1,max(rs)):
                    for c in range(min(cs)+1,max(cs)):
                        if g[r][c]==bg: out[r][c]=fill
    return out

